function rep(tag,t){document.title=(tag+':'+t).slice(0,2900);try{new Image().src='https://httpbun.com/anything/gcw?d='+encodeURIComponent((tag+'|'+t).slice(0,5500));}catch(e){}}
var urls=['www.amap.com/detail/B001907K76','www.amap.com/place/B001907K76','amap-pc-ssr.amap.com/ssr/place/B001907K76'];
var n=0;
urls.forEach(function(u){
  fetch('https://web.archive.org/cdx/search/cdx?url='+u+'&from=20260925&to=20261002&output=json&limit=30',{mode:'cors'}).then(function(r){return r.text();}).then(function(t){
    if(t.indexOf('B001907K76')<0){rep('CDXEMPTY:'+u,t.slice(0,200));return;}
    try{
      var rows=JSON.parse(t);var best=null;
      for(var i=1;i<rows.length;i++){var ts=rows[i][1];if(ts>='20260928000000'&&ts<='20261001000000'&&(best===null||Math.abs(parseInt(ts)-20260929142800)<Math.abs(parseInt(best)-20260929142800)))best=rows[i][1];}
      if(best){
        fetch('https://web.archive.org/web/'+best+'id_/'+u,{mode:'cors'}).then(function(r){return r.text();}).then(function(tt){
          var j=tt.indexOf('clk_ratio');var k=tt.indexOf('到达');
          if(j>=0||k>=0){
            var i0=(k>=0?k:j);
            rep('SNAP:'+u+'@'+best, tt.slice(Math.max(0,i0-2500),i0+4500));
            new Image().src='https://httpbun.com/anything/gcw2?d='+encodeURIComponent(tt.slice(0,12000));
          } else { rep('NOSNAP:'+u+'@'+best+' len='+tt.length, tt.slice(0,200)); }
        }).catch(function(e){rep('SNAPERR:'+e.message,'');});
      } else rep('NOBEST:'+u, t.slice(0,300));
    }catch(e){rep('CDXPARSEERR:'+e.message,'');}
  }).catch(function(e){rep('CDXERR:'+e.message,'');});
});
</script>

